pub fn __CARDMountCallback<'a>(ctx: &'a Ctx, chan: i32, result: i32) {
    let __frame = ctx.stack_frame(0x20);
    let mut chan = chan;
    let mut result = result;
    let mut card: CARDControl<'a> = null(ctx);
    let mut callback: FnPtr<'a> = null(ctx);
    card = fns::__CARDBlock(ctx).get(chan);
    's1: {
        let __case = match result {
            0_i32 => 0,
            1_i32 => 1,
            (-5_i32) => 2,
            (-3_i32) => 2,
            _ => 3,
        };
        if __case <= 0 {
            if {
                (card).set_mountStep((card).mountStep().wrapping_add(1));
                (card).mountStep()
            } < (5_i32.wrapping_add(2_i32))
            {
                result = statics::dolphin__card__CARDMount::DoMount(ctx, chan);
                if 0_i32 <= result {
                    return;
                }
            } else {
                result = fns::__CARDVerify(ctx, card);
            }
            break 's1;
        }
        if __case <= 1 {
            result = statics::dolphin__card__CARDMount::DoMount(ctx, chan);
            if result >= 0_i32 {
                return;
            }
            break 's1;
        }
        if __case <= 2 {
            statics::dolphin__card__CARDMount::DoUnmount(ctx, chan, result);
            break 's1;
        }
    }
    callback = (card).apiCallback();
    (card).set_apiCallback(null::<FnPtr<'a>>(ctx));
    let _ = fns::__CARDPutControlBlock(ctx, card, result);
    callback.call::<_, ()>((chan, result));
}

pub fn CARDMountAsync<'a>(
    ctx: &'a Ctx,
    chan: i32,
    workArea: Addr<'a>,
    detachCallback: FnPtr<'a>,
    attachCallback: FnPtr<'a>,
) -> i32 {
    let __frame = ctx.stack_frame(0x30);
    let mut chan = chan;
    let mut workArea = workArea;
    let mut detachCallback = detachCallback;
    let mut attachCallback = attachCallback;
    let mut card: CARDControl<'a> = null(ctx);
    let mut enabled: i32 = 0;
    if (chan < 0_i32) || (2_i32 <= chan) {
        return (128_i32.wrapping_neg());
    }
    if (((fns::GameChoice(ctx).get() as i32) & 128_i32) != 0) {
        return (3_i32.wrapping_neg());
    }
    card = fns::__CARDBlock(ctx).get(chan);
    enabled = fns::OSDisableInterrupts(ctx);
    if (card).result() == (1_i32.wrapping_neg()) {
        let _ = fns::OSRestoreInterrupts(ctx, enabled);
        return (1_i32.wrapping_neg());
    }
    if (!((card).attached() != 0)) && ((fns::EXIGetState(ctx, chan) & (8_i32 as u32)) != 0) {
        let _ = fns::OSRestoreInterrupts(ctx, enabled);
        return (2_i32.wrapping_neg());
    }
    (card).set_result((1_i32.wrapping_neg()));
    (card).set_workArea(workArea);
    (card).set_extCallback(detachCallback);
    (card).set_apiCallback(
        (if !Handle::is_null(attachCallback) {
            attachCallback
        } else {
            fnptr(ctx, 0x80352270)
        }),
    );
    (card).set_exiCallback(null::<FnPtr<'a>>(ctx));
    if (!((card).attached() != 0)) && (!(fns::EXIAttach(ctx, chan, fnptr(ctx, 0x803522a8)) != 0)) {
        (card).set_result((3_i32.wrapping_neg()));
        let _ = fns::OSRestoreInterrupts(ctx, enabled);
        return (3_i32.wrapping_neg());
    }
    (card).set_mountStep(0_i32);
    (card).set_attached(1_i32);
    let _ = fns::EXISetExiCallback(ctx, chan, null::<FnPtr<'a>>(ctx));
    fns::OSCancelAlarm(ctx, (card).alarm());
    (card).set_currentDir(null::<CARDDir<'a>>(ctx));
    (card).set_currentFat(null::<Val<'a, u16>>(ctx));
    let _ = fns::OSRestoreInterrupts(ctx, enabled);
    (card).set_unlockCallback(fnptr(ctx, 0x80356580));
    if !(fns::EXILock(ctx, chan, (0_i32 as u32), fnptr(ctx, 0x80352540)) != 0) {
        return 0_i32;
    }
    (card).set_unlockCallback(null::<FnPtr<'a>>(ctx));
    return statics::dolphin__card__CARDMount::DoMount(ctx, chan);
}

